import SwiftUI

/// An SVG path (absolute `M`/`L`/`C`/`Z` only) rendered as a SwiftUI `Shape`, aspect-fit and
/// centered into the target rect from a 24×24 viewBox.
///
/// Brand marks are drawn as vectors rather than asset-catalog images because the agent avatar is
/// shared source compiled into *both* clients, and the macOS app ships no compiled asset catalog
/// (its DMG build makes an `.icns` with `iconutil`, never runs `actool`) — so an `Image("…")`
/// would resolve on iOS yet render blank on macOS. A vector path renders identically on both.
struct VectorMark: Shape {
    /// Path data normalized offline to absolute `M L C Z` (elliptical arcs flattened to cubics).
    /// Numbers are whitespace-separated; a command letter may be glued to its first number
    /// (e.g. `C-0.06 …`). Filled non-zero, matching the source artwork's winding.
    let pathData: String
    var viewBox: CGFloat = 24

    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width, rect.height) / viewBox
        let ox = rect.midX - viewBox * scale / 2
        let oy = rect.midY - viewBox * scale / 2
        func map(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: ox + x * scale, y: oy + y * scale) }

        let tokens = Self.tokenize(pathData)
        var path = Path()
        var i = 0
        func num() -> CGFloat {
            defer { i += 1 }
            if i < tokens.count, case let .number(v) = tokens[i] { return v }
            return 0
        }
        var last: Character = "M"
        while i < tokens.count {
            var cmd = last
            if case let .command(c) = tokens[i] { cmd = c; i += 1 }
            last = cmd
            switch cmd {
            case "M": path.move(to: map(num(), num()))
            case "L": path.addLine(to: map(num(), num()))
            case "C":
                let c1 = map(num(), num()), c2 = map(num(), num()), end = map(num(), num())
                path.addCurve(to: end, control1: c1, control2: c2)
            case "Z": path.closeSubpath()
            default: i += 1   // unreachable for normalized data; guards against a stray token
            }
        }
        return path
    }

    private enum Token { case command(Character); case number(CGFloat) }

    private static func tokenize(_ s: String) -> [Token] {
        var tokens: [Token] = []
        var buf = ""
        func flush() {
            if !buf.isEmpty { tokens.append(.number(CGFloat(Double(buf) ?? 0))); buf = "" }
        }
        for ch in s {
            switch ch {
            case "M", "L", "C", "Z": flush(); tokens.append(.command(ch))
            case " ", ",", "\n", "\t": flush()
            case "-", "+":
                // A sign starts a new number. Our data space-separates every number, but split
                // defensively — unless it's an exponent sign (no exponents in the normalized data).
                if !buf.isEmpty, buf.last != "e", buf.last != "E" { flush() }
                buf.append(ch)
            default: buf.append(ch)
            }
        }
        flush()
        return tokens
    }
}

/// Which provider brand a mark should render. Cases are exactly the web preset table
/// (`PROVIDER_PRESETS` in src/shared) that ships an official glyph, so a provider looks the same
/// in the browser and in the native clients; anything else is `.generic` — the neutral grey tile
/// with a letter monogram, matching web's `NEUTRAL_BRAND`, so a provider we have no artwork for is
/// labelled truthfully rather than wearing another vendor's mark.
///
/// The paths and colours below are generated from the two web sources — `providerGlyphs.ts` and
/// `providerPresets.ts` — with the glyphs normalized offline into the absolute `M L C Z` subset
/// `VectorMark` parses (relative commands, H/V, S/T shorthand and elliptical arcs are all resolved
/// there, and each result was diffed against the browser rendering before being pasted in).
enum AgentBrand {
    case claude, codex, gemini, deepseek, kimi, glm, minimax, qwen, generic

    /// Resolve from a preset key or provider slug. Engine slugs map to the preset they run
    /// (`claude` → Anthropic, `codex` → OpenAI), mirroring web's `ENGINE_PRESET`.
    static func from(_ provider: String?) -> AgentBrand {
        switch provider?.lowercased() {
        case "codex", "openai":            return .codex
        case "claude", "anthropic", nil:   return .claude
        case "gemini", "google":           return .gemini
        case "deepseek":                   return .deepseek
        case "kimi", "moonshot":           return .kimi
        case "glm", "zai", "z.ai":         return .glm
        case "minimax":                    return .minimax
        case "qwen", "dashscope":          return .qwen
        default:                           return .generic
        }
    }

    /// The official mark, or `nil` for `.generic` (which renders a monogram instead).
    var markPath: String? {
        switch self {
        case .claude:   return Self.claudeMark
        case .codex:    return Self.codexMark
        case .gemini:   return Self.geminiMark
        case .deepseek: return Self.deepseekMark
        case .kimi:     return Self.kimiMark
        case .glm:      return Self.glmMark
        case .minimax:  return Self.minimaxMark
        case .qwen:     return Self.qwenMark
        case .generic:  return nil
        }
    }

    /// Mark size as a fraction of the tile — web draws every glyph at 0.56 of the tile, and the
    /// marks share one 24×24 viewBox, so a single ratio keeps the set optically even.
    var markScale: CGFloat { self == .generic ? 0 : 0.56 }

    /// The tile's gradient stops, straight from the web preset's `brand.from`/`brand.to`.
    var gradient: (from: Color, to: Color) {
        switch self {
        case .claude: return (Color(red: 0.851, green: 0.467, blue: 0.341), Color(red: 0.757, green: 0.373, blue: 0.235))   // #d97757 → #c15f3c
        case .codex: return (Color(red: 0.294, green: 0.318, blue: 0.345), Color(red: 0.122, green: 0.133, blue: 0.149))   // #4b5158 → #1f2226
        case .gemini: return (Color(red: 0.259, green: 0.522, blue: 0.957), Color(red: 0.608, green: 0.447, blue: 0.796))   // #4285f4 → #9b72cb
        case .deepseek: return (Color(red: 0.357, green: 0.486, blue: 1.000), Color(red: 0.227, green: 0.341, blue: 0.910))   // #5b7cff → #3a57e8
        case .kimi: return (Color(red: 0.227, green: 0.227, blue: 0.227), Color(red: 0.067, green: 0.067, blue: 0.067))   // #3a3a3a → #111111
        case .glm: return (Color(red: 0.200, green: 0.714, blue: 0.690), Color(red: 0.118, green: 0.557, blue: 0.557))   // #33b6b0 → #1e8e8e
        case .minimax: return (Color(red: 1.000, green: 0.357, blue: 0.463), Color(red: 0.882, green: 0.114, blue: 0.282))   // #ff5b76 → #e11d48
        case .qwen: return (Color(red: 0.478, green: 0.447, blue: 1.000), Color(red: 0.310, green: 0.275, blue: 0.898))   // #7a72ff → #4f46e5
        case .generic: return (Color(red: 0.604, green: 0.627, blue: 0.659), Color(red: 0.420, green: 0.443, blue: 0.471))   // #9aa0a8 → #6b7178
        }
    }

